class Unit:
    """Standardized units of measure (part 2 appendix 3.4)."""

    #: Amperes (current)
    A = "A"
    #: Arbitrary Strength Unit (Signal Strength)
    ASU = "ASU"
    #: Bytes
    B = "B"
    #: Degrees (temperature)
    CELSIUS = "Celsius"
    #: Decibel (for example Signal Strength)
    DB = "dB"
    #: Power relative to 1mW (^10^log(P/1mW))
    DBM = "dBm"
    #: Degrees (angle/rotation)
    DEG = "Deg"
    #: Degrees (temperature)
    FAHRENHEIT = "Fahrenheit"
    #: Hertz (frequency)
    HZ = "Hz"
    #: milliHertz (frequency)
    MHZ = "mHz"
    #: Degrees Kelvin (temperature)
    K = "K"
    #: Lux (Light Intensity)
    LX = "lx"
    #: Meter (length)
    M = "m"
    #: m/s^2^ (Acceleration)
    MS2 = "ms2"
    #: Newtons (Force)
    N = "N"
    #: Ohm (Impedance)
    OHM = "Ohm"
    #: kiloPascal (Pressure)
    KPA = "kPa"
    #: Percentage
    PERCENT = "Percent"
    #: Relative Humidity%
    RH = "RH"
    #: Revolutions per Minute
    RPM = "RPM"
    #: Seconds (Time)
    S = "s"
    #: Voltage (DC or r.m.s.
    V = "V"
    #: Volt-Ampere (apparent power)
    VA = "VA"
    #: kiloVolt-Ampere (apparent power)
    KVA = "kVA"
    #: Volt-Ampere-hours (apparent energy)
    VAH = "VAh"
    #: kiloVolt-Ampere-hours (apparent energy)
    KVAH = "kVAh"
    #: vars (reactive power)
    VAR = "var"
    #: kilovars (reactive power)
    KVAR = "kvar"
    #: var-hours (reactive energy)
    VARH = "varh"
    #: kilovar-hours (reactive energy)
    KVARH = "kvarh"
    #: Watts (power)
    W = "W"
    #: kilowatts (power)
    KW = "kW"
    #: Watt-hours (energy).
    WH = "Wh"
    #: kilowatt-hours (energy)
    KWH = "kWh"


UNITS: tuple[str, ...] = (
    Unit.A,
    Unit.ASU,
    Unit.B,
    Unit.CELSIUS,
    Unit.DB,
    Unit.DBM,
    Unit.DEG,
    Unit.FAHRENHEIT,
    Unit.HZ,
    Unit.MHZ,
    Unit.K,
    Unit.LX,
    Unit.M,
    Unit.MS2,
    Unit.N,
    Unit.OHM,
    Unit.KPA,
    Unit.PERCENT,
    Unit.RH,
    Unit.RPM,
    Unit.S,
    Unit.V,
    Unit.VA,
    Unit.KVA,
    Unit.VAH,
    Unit.KVAH,
    Unit.VAR,
    Unit.KVAR,
    Unit.VARH,
    Unit.KVARH,
    Unit.W,
    Unit.KW,
    Unit.WH,
    Unit.KWH,
)


class ReasonCode:
    """Reason codes for ``StatusInfo.reason_code`` (part 2 appendix 5)."""

    #: (Charging Profiles) A charging profile with same _stackLevel - chargingProfilePurpose_...
    DUPLICATE_PROFILE = "DuplicateProfile"
    #: (Charging Profiles) Provided _chargingProfile_ contains invalid elements.
    INVALID_PROFILE = "InvalidProfile"
    #: (Charging Profiles) Provided _chargingProfile_ has an id that is within an invalid range.
    INVALID_PROFILE_ID = "InvalidProfileId"
    #: (Charging Profiles) Provided _chargingSchedule_ contains invalid elements.
    INVALID_SCHEDULE = "InvalidSchedule"
    #: (Charging Profiles) Provided value for _stackLevel_ is invalid.
    INVALID_STACK_LEVEL = "InvalidStackLevel"
    #: (Charging Profiles) Provided operationMode is invalid for this chargingProfilePurpose
    INVALID_OPERATION_MODE = "InvalidOperationMode"
    #: (Charging Profiles) A frequency-watt curve is missing in a charging schedule period...
    NO_FREQ_WATT_CURVE = "NoFreqWattCurve"
    #: (Charging Profiles) Phase selection for a DC EVSE is not supported
    NO_PHASE_FOR_DC = "NoPhaseForDC"
    #: (Charging Profiles) Phase conflict between applicable charging profiles
    PHASE_CONFLICT = "PhaseConflict"
    #: (Charging Profiles) A signal-watt curve is missing in a charging schedule period when...
    NO_SIGNAL_WATT_CURVE = "NoSignalWattCurve"
    #: (Charging Profiles) A charging profile of the same purpose is submitted too frequently
    RATE_LIMIT_EXCEEDED = "RateLimitExceeded"
    #: (Charging Profiles) The requested charging profile kind is not supported
    UNSUPPORTED_KIND = "UnsupportedKind"
    #: (Charging Profiles) The requested charging profile purpose is not supported
    UNSUPPORTED_PURPOSE = "UnsupportedPurpose"
    #: (Charging Profiles) A _chargingRateUnit_ is provided that is not supported.
    UNSUPPORTED_RATE_UNIT = "UnsupportedRateUnit"
    #: (Charging Station) BootNotification of Charging Station has not (yet) been accepted...
    CS_NOT_ACCEPTED = "CSNotAccepted"
    #: (Charging Station) The connector has its own fixed cable that cannot be unlocked.
    FIXED_CABLE = "FixedCable"
    #: (Charging Station) No cable is connected at this time.
    NO_CABLE = "NoCable"
    #: (Charging Station) Connector Id is not known on EVSE
    UNKNOWN_CONNECTOR_ID = "UnknownConnectorId"
    #: (Charging Station) Connector type is not known on EVSE
    UNKNOWN_CONNECTOR_TYPE = "UnknownConnectorType"
    #: (Charging Station) EVSE is not known on Charging Stations
    UNKNOWN_EVSE = "UnknownEvse"
    #: (Swap Station) Battery State of Health is too low
    BATTERY_SO_H_LOW = "BatterySoHLow"
    #: (Swap Station) Battery State of Charge has unacceptable value
    BATTERY_SO_C = "BatterySoC"
    #: (Swap Station) Battery is damaged
    BATTERY_DAMAGED = "BatteryDamaged"
    #: (Swap Station) Battery has unknown serial number
    BATTERY_UNKNOWN = "BatteryUnknown"
    #: (Swap Station) Battery type not accepted
    BATTERY_TYPE = "BatteryType"
    #: (Swap Station) No battery available for swapping
    NO_BATTERY_AVAILABLE = "NoBatteryAvailable"
    #: (Network Configuration) A network configuration variable of an NetworkConfiguration...
    PRIORITY_NETWORK_CONF = "PriorityNetworkConf"
    #: (Network Configuration) A value for configurationSlot is used that is not present in...
    INVALID_CONF_SLOT = "InvalidConfSlot"
    #: (Network Configuration) Some values in NetworkConfiguration instance are invalid
    INVALID_NETWORK_CONF = "InvalidNetworkConf"
    #: (Network Configuration) Security profile downgrade is not allowed
    NO_SECURITY_DOWNGRADE = "NoSecurityDowngrade"
    #: (Miscellaneous) A _requestId_ is provided, that has already been used for this...
    DUPLICATE_REQUEST_ID = "DuplicateRequestId"
    #: (Miscellaneous) Message should not be sent at this moment in current scenario.
    INVALID_MESSAGE_SEQ = "InvalidMessageSeq"
    #: (Miscellaneous) Information needed for operation is missing from Device Model
    MISSING_DEV_MODEL_INFO = "MissingDevModelInfo"
    #: (Miscellaneous) No error has occurred, but some extra information is in...
    NO_ERROR = "NoError"
    #: (Miscellaneous) No object(s) found that match a provided ID or criteria.
    NOT_FOUND = "NotFound"
    #: (Miscellaneous) No reason is specified, but some extra information is in...
    UNSPECIFIED = "Unspecified"
    #: (Miscellaneous) This request is not supported.
    UNSUPPORTED_REQUEST = "UnsupportedRequest"
    #: (Operations and Permissions) Operation is not possible, because a firmware update is in progress.
    FW_UPDATE_IN_PROGRESS = "FwUpdateInProgress"
    #: (Operations and Permissions) Feature is not enabled.
    NOT_ENABLED = "NotEnabled"
    #: (Operations and Permissions) Targeted variable is read-only and cannot be set.
    READ_ONLY = "ReadOnly"
    #: (Operations and Permissions) Targeted variable is write-only and cannot be read.
    WRITE_ONLY = "WriteOnly"
    #: (Security) Provided CSR is invalid
    INVALID_CSR = "InvalidCSR"
    #: (Security) Provided certificate is invalid.
    INVALID_CERTIFICATE = "InvalidCertificate"
    #: (Security) Provided URL is invalid.
    INVALID_URL = "InvalidURL"
    #: (Security) HTTP Redirection is not allowed
    REDIRECT_NOT_ALLOWED = "RedirectNotAllowed"
    #: (System Errors) Operation cannot be completed due to an internal error.
    INTERNAL_ERROR = "InternalError"
    #: (System Errors) Operation not possible, because system does not have enough memory.
    OUT_OF_MEMORY = "OutOfMemory"
    #: (System Errors) Operation not possible, because system does not have enough storage.
    OUT_OF_STORAGE = "OutOfStorage"
    #: (Transactions) Provided _idToken_ is not valid.
    INVALID_ID_TOKEN = "InvalidIdToken"
    #: (Transactions) A transaction is in progress.
    TX_IN_PROGRESS = "TxInProgress"
    #: (Transactions) There is no such transaction.
    TX_NOT_FOUND = "TxNotFound"
    #: (Transactions) A transaction had already started (e.g.
    TX_STARTED = "TxStarted"
    #: (Values and Ranges) An invalid value has been provided.
    INVALID_VALUE = "InvalidValue"
    #: (Values and Ranges) A parameter that is required for the request is missing.
    MISSING_PARAM = "MissingParam"
    #: (Values and Ranges) Provided element is too large to handle.
    TOO_LARGE_ELEMENT = "TooLargeElement"
    #: (Values and Ranges) Too many elements have been provided.
