class SecurityEvent:
    """Standardized security events (part 2 appendix 1)."""

    #: The Charging Station firmware is updated
    FIRMWARE_UPDATED = "FirmwareUpdated"
    #: The authentication credentials provided by the Charging Station were rejected by the...
    FAILED_TO_AUTHENTICATE_AT_CSMS = "FailedToAuthenticateAtCsms"
    #: The authentication credentials provided by the CSMS were rejected by the Charging...
    CSMS_FAILED_TO_AUTHENTICATE = "CsmsFailedToAuthenticate"
    #: The system time on the Charging Station was changed more than...
    SETTING_SYSTEM_TIME = "SettingSystemTime"
    #: The Charging Station has booted
    STARTUP_OF_THE_DEVICE = "StartupOfTheDevice"
    #: The Charging Station was rebooted or reset
    RESET_OR_REBOOT = "ResetOrReboot"
    #: The security log was cleared
    SECURITY_LOG_WAS_CLEARED = "SecurityLogWasCleared"
    #: Security parameters, such as keys or the security profile used, were changed
    RECONFIGURATION_OF_SECURITY_PARAMETERS = "ReconfigurationOfSecurityParameters"
    #: The Flash or RAM memory of the Charging Station is getting full
    MEMORY_EXHAUSTION = "MemoryExhaustion"
    #: The Charging Station has received messages that are not valid OCPP messages, if...
    INVALID_MESSAGES = "InvalidMessages"
    #: The Charging Station has received a replayed message (other than the CSMS trying to...
    ATTEMPTED_REPLAY_ATTACKS = "AttemptedReplayAttacks"
    #: The physical tamper detection sensor was triggered
    TAMPER_DETECTION_ACTIVATED = "TamperDetectionActivated"
    #: The firmware signature is not valid
    INVALID_FIRMWARE_SIGNATURE = "InvalidFirmwareSignature"
    #: The certificate used to verify the firmware signature is not valid
    INVALID_FIRMWARE_SIGNING_CERTIFICATE = "InvalidFirmwareSigningCertificate"
    #: The certificate that the CSMS uses was not valid or could not be verified
    INVALID_CSMS_CERTIFICATE = "InvalidCsmsCertificate"
    #: The certificate sent to the Charging Station using the CertificateSignedRequest...
    INVALID_CHARGING_STATION_CERTIFICATE = "InvalidChargingStationCertificate"
    #: The Charging Station discarded the renewed client certificate, because it was unable...
    DISCARDED_RENEWED_CLIENT_CERTIFICATE = "DiscardedRenewedClientCertificate"
    #: The TLS version used by the CSMS is lower than 1.2 and is not allowed by the...
    INVALID_TLS_VERSION = "InvalidTLSVersion"
    #: The CSMS did only allow connections using TLS cipher suites that are not allowed by...
    INVALID_TLS_CIPHER_SUITE = "InvalidTLSCipherSuite"
    #: Successful login to the local maintenance interface.
    MAINTENANCE_LOGIN_ACCEPTED = "MaintenanceLoginAccepted"
    #: Failed login attempt to the local maintenance interface.
    MAINTENANCE_LOGIN_FAILED = "MaintenanceLoginFailed"


